pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes == "ping" {
        return Ok(Msg::Ping);
    }

    let mut fields = bytes.splitn(3, '|');
    if fields.next() == Some("v:2") && fields.next() == Some("hello") {
        if let Some(name) = fields.next() {
            return Ok(Msg::Hello(name.into()));
        }
    }

    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
